import sys

def solve():
    input = sys.stdin.read().splitlines()
    T = int(input[0])
    for P in input[1:T+1]:
        days = 0
        max_jump = 1
        i = 0
        n = len(P)
        while i < n:
            if P[i] == '#':
                i += 1
            else:
                next_hash = i + 1
                while next_hash < n and P[next_hash] != '#':
                    next_hash += 1
                jump_needed = next_hash - i
                if jump_needed > max_jump:
                    days += 1
                    max_jump = jump_needed
                i = next_hash
        print(days)

solve()
